import {renderFishLab} from './fish-lab.js';
import {fishEnergyTrial} from './fish-energy.js';
import {selectedFishPond} from './fish-selection.js';
import {fishFeederReason,ownsFishFeeder} from './fish-feeder.js';
import {fishFilterReason} from './fish-filter.js';
import {FISH} from './fish-config.js';
import {fishReady,fishGrade} from './fish-stock.js';
import {el} from './dom.js';import {t} from './locales.js';import {fishSnapshot} from './fish-snapshot.js';import {fishSupply,fishCount} from './fish-state.js';
export const FISH_STATIONS=Object.freeze(['pond','feed','aerator','harvest','water','market']);
/** @param {import('./engine.js').State} state @param {string} selected @param {(type:import('./engine.js').CommandType,extra?:Partial<import('./engine.js').Command>)=>void} send */
export function renderFishPanel(state,selected,send){
 el('fish-panel').hidden=!selected;if(!selected)return;const snap=fishSnapshot(state),g=state.fish,id=selectedFishPond(state),p=g?.ponds.find(p=>p.id===id),pond=snap.ponds.find(p=>p.id===id);el('fish-heading').textContent=t('fishStation_'+selected)+(g&&g.ponds.length>1?' · '+t('fishPondLabel')+' '+id:'');el('fish-selection-copy').textContent=snap.preview?t('fishPreviewCopy'):t('fishStationInfo_'+selected);const values=el('fish-status');values.replaceChildren();
 for(const [key,value]of [['fishCount',String(pond?.count||0)],['fishReady',String(pond?.ready||0)],['fishAeration',t(pond?.aerating?'fishOn':'fishOff')],['fishEnergyPlan',(p?.efficient?FISH.efficientAirTicks:FISH.airTicks)+' h / '+t('coins')],['fishFeedStore',String(g?fishSupply(g.feed):0)+' g'],['fishWaterCredit',String(g?fishSupply(g.water):0)+' L']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=t(key);dd.textContent=value;values.append(dt,dd);}
 const actions=el('fish-actions');actions.replaceChildren();
 /** @param {string} key @param {string} label @param {()=>void} run @param {string} [reason] */
 function button(key,label,run,reason=''){const b=document.createElement('button');b.type='button';b.className='action-button';b.dataset.fishAction=key;b.textContent=label;b.disabled=!!reason;if(reason){const help=document.createElement('p');help.id='fish-help-'+key;help.textContent=t(reason);b.title=t(reason);b.setAttribute('aria-describedby',help.id);actions.append(help);}b.addEventListener('click',run);actions.append(b);}
 const inspect=()=>button('inspect',t('fishAction_inspect'),()=>send('fish.inspect',{fishPond:id}),snap.preview?'fishNotVisited':'');
 if(selected==='feed'){if(p){if(ownsFishFeeder(state,id))button('toggleFeeder',t(p.autoFeeder?'fishStopFeeder':'fishStartFeeder'),()=>send('fish.toggleFeeder',{fishPond:id}));else button('buyFeeder',t('fishBuyFeeder')+' · '+FISH.feederCoins+' '+t('coins'),()=>send('fish.buyFeeder',{fishPond:id}),fishFeederReason(state,p));const note=document.createElement('p');note.dataset.fishFeederStatus='';note.textContent=t('fishFeederHelp')+' '+t(p.autoFeeder?'fishFeederOn':'fishFeederOff');actions.append(note);}const amount=p?Math.min(1000,fishCount(p)*48):0;button('feed',t('fishAction_feed'),()=>send('fish.feed',{fishPond:id}),!p?'fishNotVisited':!fishCount(p)?'fishEmpty':p.lastFeedTick===state.tick?'fishFedThisHour':g&&fishSupply(g.feed)<amount?'fishNoFeed':'');button('buyFeed',t('fishBuyFeed8'),()=>send('fish.buyFeed',{fishPond:id}),state.coins<8?'noCoins':'');inspect();}
 else if(selected==='aerator'){const trial=fishEnergyTrial(state,id),note=document.createElement('p');note.dataset.fishEnergyTrial='';note.textContent=t('fishEnergyTrial')+' '+Math.min(trial.hours,trial.period)+' / '+trial.period+' h. '+t('fishEnergyReference')+' '+trial.basicCoins+' '+t('coins')+'; '+t('fishEnergyMeasured')+' '+trial.efficientCoins+' '+t('coins')+'. '+t('fishEnergyCapital');actions.append(note);button('energyTrial',t(g?.mission.completed.includes('energy')?'fishEnergyDone':'fishClaimEnergy'),()=>send('fish.claimEnergy',{fishPond:id}),g?.mission.completed.includes('energy')?'fishEnergyDone':!trial.eligible?'fishEnergyLocked':'');button('aerate',t(p?.aeratorOn?'fishTurnAirOff':'fishAction_aerate'),()=>send('fish.aerate',{fishPond:id}),!p||!g?'fishNotVisited':!p.aeratorOn&&g.air.starter+g.air.recovery+p.airPaidTicks===0&&state.coins<1?'fishNoEnergy':'');button('upgradeAir',t(p?.efficient?'fishEfficient':'fishUpgradeAir')+' · '+FISH.efficiencyCoins+' '+t('coins'),()=>send('fish.upgradeAir',{fishPond:id}),p?.efficient?'fishUpgradeExists':!g?.stats.saleActions?'fishSellFirst':state.coins<FISH.efficiencyCoins?'noCoins':'');inspect();}
 else if(selected==='water'){if(p){button('filter',t(p.biofilter?'fishFilterOwned':'fishBuyFilter')+' · '+FISH.filterCoins+' '+t('coins'),()=>send('fish.buyFilter',{fishPond:id}),fishFilterReason(state,p));const note=document.createElement('p');note.dataset.fishFilterStatus='';note.textContent=t('fishFilterHelp')+' '+t(!p.biofilter?'fishFilterAbsent':!p.aeratorOn?'fishFilterOff':p.filterPaidTicks||state.coins>=1?'fishFilterReady':'fishFilterNoEnergy');actions.append(note);}button('exchange',t('fishExchange5'),()=>send('fish.exchange',{fishPond:id}),!p||!g?'fishNotVisited':fishSupply(g.water)<200&&state.coins<3?'fishNoWater':'');inspect();}
 else if(selected==='harvest'){const ready=p?.cohorts.filter(c=>fishReady(c,state.tick))||[];if(!ready.length)button('harvest',t('fishAction_harvest'),()=>{},'fishNoReady');for(const c of ready){button('harvest',t('fishAction_harvest')+' · '+c.count+' '+t('fishCount')+' · '+(c.count*c.massG/1000)+' kg · '+fishGrade(c),()=>send('fish.harvest',{fishPond:id,fishCohort:c.id}));actions.lastElementChild?.setAttribute('data-fish-harvest',c.id);}}
 else if(selected==='pond')inspect();
 button('market',t('fishAction_market'),()=>document.dispatchEvent(new Event('marketopen')));
 if(g&&g.stats.inspections>0){const why=document.createElement('p');why.dataset.fishInspection='';const oxygen=(pond?.oxygenMg||0)/4000,tan=(pond?.tanMg||0)/4000;why.textContent=t('fishOxygen')+': '+t(oxygen<3?'fishLow':oxygen<5?'fishWatch':'fishGood')+'. '+t(tan>=1?'fishWasteWatch':'fishWaterSteady')+' '+t('fishWaterDisclaimer');actions.append(why);}
 if(p)renderFishLab(state,p,actions);
}
